using FCG.Games.Application.Abstractions;using FCG.Games.Domain.Entities;using Microsoft.EntityFrameworkCore;namespace FCG.Games.Infrastructure.Persistence;public sealed class GamesRepository(GamesDbContext db):IGamesRepository{public Task<Game?> GetGameAsync(int id)=>db.Games.FirstOrDefaultAsync(x=>x.Id==id);public Task<List<Game>> GetGamesAsync()=>db.Games.AsNoTracking().Where(x=>x.Active).ToListAsync();public async Task AddGameAsync(Game g)=>await db.Games.AddAsync(g);public async Task AddPurchaseAsync(Purchase p)=>await db.Purchases.AddAsync(p);public async Task AddLibraryItemAsync(LibraryItem i)=>await db.Library.AddAsync(i);public Task<bool> OwnsAsync(int u,int g)=>db.Library.AnyAsync(x=>x.UserId==u&&x.GameId==g);public Task<int> LibraryCountAsync(int u)=>db.Library.CountAsync(x=>x.UserId==u);public async Task<List<Game>> GetLibraryAsync(int u){var ids=await db.Library.Where(x=>x.UserId==u).Select(x=>x.GameId).ToListAsync();return await db.Games.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToListAsync();}public Task SaveAsync()=>db.SaveChangesAsync();}
